# Create HuggingFace Spaces API client module
hf_client_script = '''#!/usr/bin/env python3
"""
OASIS v3 HuggingFace Spaces API Client - Ultra-Lightweight
===========================================================
Specialized client for connecting Termux orchestrator to HF Spaces backend.
Uses ONLY Python standard library + urllib for maximum compatibility.

ZERO HEAVY DEPENDENCIES - TERMUX OPTIMIZED

Author: OASIS Development Team
Version: 3.0.0-production
License: MIT
"""

import urllib.request
import urllib.parse
import urllib.error
import json
import time
import os
import logging
from datetime import datetime
import hashlib
import base64

class HFSpacesClient:
    """Ultra-lightweight HuggingFace Spaces API client"""

    def __init__(self, space_url, api_token=None, timeout=30):
        """Initialize HF Spaces client"""
        self.space_url = space_url.rstrip('/')
        self.api_token = api_token
        self.timeout = timeout
        self.session_id = self._generate_session_id()
        self.request_count = 0

        # Setup logging
        self.logger = logging.getLogger('HFClient')

        # Connection settings
        self.max_retries = 3
        self.retry_delay = 1.0

        # Request headers
        self.default_headers = {
            'Content-Type': 'application/json',
            'User-Agent': 'OASIS-v3-HFClient/3.0.0',
            'X-Client-Session': self.session_id
        }

        if self.api_token:
            self.default_headers['Authorization'] = f'Bearer {self.api_token}'

        self.logger.info(f"🔗 HF Client initialized: {self.space_url}")
        self.logger.info(f"🆔 Session ID: {self.session_id}")

    def _generate_session_id(self):
        """Generate unique session identifier"""
        timestamp = str(int(time.time()))
        return hashlib.md5(f"hf_client_{timestamp}".encode()).hexdigest()[:10]

    def _make_request(self, endpoint, data=None, method='POST', custom_headers=None):
        """Make HTTP request with retry logic"""
        url = f"{self.space_url}{endpoint}"

        # Prepare headers
        headers = self.default_headers.copy()
        if custom_headers:
            headers.update(custom_headers)

        # Prepare data
        if data is not None:
            data = json.dumps(data).encode('utf-8')

        self.request_count += 1
        start_time = time.time()

        for attempt in range(self.max_retries + 1):
            try:
                # Create request
                req = urllib.request.Request(url, data=data, headers=headers, method=method)

                # Make request
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    response_data = response.read().decode('utf-8')

                    # Parse response
                    if response_data:
                        result = json.loads(response_data)
                    else:
                        result = {}

                    response_time = time.time() - start_time

                    self.logger.info(f"✅ HF request successful: {endpoint} ({response_time:.2f}s)")

                    return {
                        "success": True,
                        "data": result,
                        "response_time": response_time,
                        "status_code": response.status,
                        "attempt": attempt + 1
                    }

            except urllib.error.HTTPError as e:
                error_msg = f"HTTP {e.code}: {e.reason}"
                self.logger.warning(f"❌ HTTP error: {error_msg} (attempt {attempt + 1})")

                if attempt == self.max_retries:
                    return {
                        "success": False,
                        "error": error_msg,
                        "status_code": e.code,
                        "response_time": time.time() - start_time,
                        "attempt": attempt + 1
                    }

            except urllib.error.URLError as e:
                error_msg = f"Connection error: {e.reason}"
                self.logger.warning(f"❌ URL error: {error_msg} (attempt {attempt + 1})")

                if attempt == self.max_retries:
                    return {
                        "success": False,
                        "error": error_msg,
                        "response_time": time.time() - start_time,
                        "attempt": attempt + 1
                    }

            except Exception as e:
                error_msg = f"Unexpected error: {str(e)}"
                self.logger.error(f"❌ {error_msg} (attempt {attempt + 1})")

                if attempt == self.max_retries:
                    return {
                        "success": False,
                        "error": error_msg,
                        "response_time": time.time() - start_time,
                        "attempt": attempt + 1
                    }

            # Wait before retry with exponential backoff
            if attempt < self.max_retries:
                wait_time = self.retry_delay * (2 ** attempt)
                self.logger.info(f"⏳ Retrying in {wait_time:.1f} seconds...")
                time.sleep(wait_time)

    def ping(self):
        """Ping the HF Space to check availability"""
        return self._make_request('/api/v1/health', method='GET')

    def analyze_sentiment(self, text, model='roberta', options=None):
        """Analyze sentiment of text"""
        data = {
            'text': text,
            'model': model,
            'session_id': self.session_id
        }

        if options:
            data.update(options)

        return self._make_request('/api/v1/sentiment', data)

    def generate_text(self, prompt, max_tokens=100, temperature=0.7, model='gpt2'):
        """Generate text using language models"""
        data = {
            'prompt': prompt,
            'max_tokens': max_tokens,
            'temperature': temperature,
            'model': model,
            'session_id': self.session_id
        }

        return self._make_request('/api/v1/generate', data)

    def classify_text(self, text, categories=None, model='distilbert'):
        """Classify text into categories"""
        data = {
            'text': text,
            'model': model,
            'session_id': self.session_id
        }

        if categories:
            data['categories'] = categories

        return self._make_request('/api/v1/classify', data)

    def process_image(self, image_data, task='classify', model='vit'):
        """Process image using vision models"""
        data = {
            'image_data': image_data,
            'task': task,
            'model': model,
            'session_id': self.session_id
        }

        return self._make_request('/api/v1/image', data)

    def summarize_text(self, text, max_length=150, model='bart'):
        """Summarize long text"""
        data = {
            'text': text,
            'max_length': max_length,
            'model': model,
            'session_id': self.session_id
        }

        return self._make_request('/api/v1/summarize', data)

    def translate_text(self, text, source_lang='auto', target_lang='en', model='mbart'):
        """Translate text between languages"""
        data = {
            'text': text,
            'source_lang': source_lang,
            'target_lang': target_lang,
            'model': model,
            'session_id': self.session_id
        }

        return self._make_request('/api/v1/translate', data)

    def batch_process(self, tasks, priority='normal'):
        """Process multiple tasks in batch"""
        data = {
            'tasks': tasks,
            'priority': priority,
            'session_id': self.session_id,
            'batch_size': len(tasks)
        }

        return self._make_request('/api/v1/batch', data)

    def get_models(self):
        """Get available models"""
        return self._make_request('/api/v1/models', method='GET')

    def get_stats(self):
        """Get system statistics"""
        return self._make_request('/api/v1/stats', method='GET')

    def get_usage(self, client_id=None):
        """Get usage statistics"""
        params = {}
        if client_id:
            params['client_id'] = client_id

        query_string = urllib.parse.urlencode(params) if params else ''
        endpoint = f'/api/v1/usage?{query_string}' if query_string else '/api/v1/usage'

        return self._make_request(endpoint, method='GET')

    def upload_file(self, file_path, file_type='auto'):
        """Upload file for processing"""
        if not os.path.exists(file_path):
            return {
                "success": False,
                "error": f"File not found: {file_path}"
            }

        try:
            with open(file_path, 'rb') as f:
                file_content = f.read()

            # Encode file content as base64
            encoded_content = base64.b64encode(file_content).decode('utf-8')

            data = {
                'file_content': encoded_content,
                'file_name': os.path.basename(file_path),
                'file_type': file_type,
                'session_id': self.session_id
            }

            return self._make_request('/api/v1/upload', data)

        except Exception as e:
            return {
                "success": False,
                "error": f"File upload error: {str(e)}"
            }

    def create_embedding(self, text, model='sentence-transformer'):
        """Create text embeddings"""
        data = {
            'text': text,
            'model': model,
            'session_id': self.session_id
        }

        return self._make_request('/api/v1/embed', data)

    def chat_completion(self, messages, model='dialogpt', max_tokens=150):
        """Generate chat responses"""
        data = {
            'messages': messages,
            'model': model,
            'max_tokens': max_tokens,
            'session_id': self.session_id
        }

        return self._make_request('/api/v1/chat', data)

    def get_client_info(self):
        """Get client information and statistics"""
        return {
            'session_id': self.session_id,
            'space_url': self.space_url,
            'request_count': self.request_count,
            'has_token': bool(self.api_token),
            'timeout': self.timeout,
            'max_retries': self.max_retries
        }

    def close_session(self):
        """Close client session"""
        try:
            data = {'session_id': self.session_id}
            result = self._make_request('/api/v1/session/close', data)
            self.logger.info(f"🔌 Session closed: {self.session_id}")
            return result
        except Exception as e:
            self.logger.error(f"❌ Error closing session: {e}")
            return {"success": False, "error": str(e)}


# Utility functions for common tasks
def create_client(space_url, api_token=None, timeout=30):
    """Create and return configured HF Spaces client"""
    return HFSpacesClient(space_url, api_token, timeout)

def test_connection(space_url, api_token=None):
    """Test connection to HF Space"""
    client = create_client(space_url, api_token)
    result = client.ping()
    client.close_session()
    return result

def batch_sentiment_analysis(space_url, texts, api_token=None):
    """Analyze sentiment for multiple texts"""
    client = create_client(space_url, api_token)

    tasks = []
    for i, text in enumerate(texts):
        tasks.append({
            'id': i,
            'type': 'sentiment',
            'data': {'text': text}
        })

    result = client.batch_process(tasks)
    client.close_session()
    return result

def quick_text_generation(space_url, prompt, api_token=None, max_tokens=100):
    """Quick text generation"""
    client = create_client(space_url, api_token)
    result = client.generate_text(prompt, max_tokens=max_tokens)
    client.close_session()
    return result


if __name__ == "__main__":
    # Example usage and testing
    import sys

    if len(sys.argv) < 2:
        print("Usage: python hf_spaces_client.py <space_url> [api_token]")
        sys.exit(1)

    space_url = sys.argv[1]
    api_token = sys.argv[2] if len(sys.argv) > 2 else None

    # Test connection
    print(f"🧪 Testing connection to {space_url}")
    result = test_connection(space_url, api_token)

    if result["success"]:
        print("✅ Connection successful!")
        print(f"📊 Response: {json.dumps(result['data'], indent=2)}")
    else:
        print(f"❌ Connection failed: {result['error']}")
        sys.exit(1)

    # Interactive test mode
    if len(sys.argv) > 2 and sys.argv[-1] == "--interactive":
        client = create_client(space_url, api_token)

        print("\\n🎮 Interactive mode. Commands: sentiment, generate, quit")

        while True:
            try:
                command = input("hf> ").strip()

                if command.lower() in ['quit', 'exit']:
                    break

                elif command.startswith('sentiment '):
                    text = command[10:]
                    result = client.analyze_sentiment(text)
                    print(f"📊 Result: {result}")

                elif command.startswith('generate '):
                    prompt = command[9:]
                    result = client.generate_text(prompt)
                    print(f"✨ Result: {result}")

                else:
                    print("❌ Unknown command")

            except KeyboardInterrupt:
                break

        client.close_session()
        print("👋 Session closed")
'''

