health_check_script = '''#!/usr/bin/env python3
"""
OASIS v3 Health Check System
Ultra-lightweight system monitoring and diagnostics
Uses only Python standard library
"""

import sys
import os
import json
import time
import subprocess
import urllib.request
import urllib.error
from datetime import datetime, timedelta
import threading
import logging

class HealthChecker:
    def __init__(self, config_path=None):
        self.config_path = config_path or os.path.join(os.path.dirname(__file__), '..', 'config', 'config.json')
        self.config = self.load_config()
        self.results = {}
        self.start_time = time.time()

    def load_config(self):
        """Load configuration from JSON file"""
        try:
            with open(self.config_path, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            print(f"⚠️  Config file not found: {self.config_path}")
            return {}
        except json.JSONDecodeError as e:
            print(f"❌ Invalid JSON in config file: {e}")
            return {}

    def check_system_resources(self):
        """Check system resources (memory, disk, CPU)"""
        print("🔍 Checking system resources...")

        try:
            # Check disk space
            disk_usage = subprocess.run(['df', '-h', os.path.expanduser('~')], 
                                      capture_output=True, text=True)
            if disk_usage.returncode == 0:
                lines = disk_usage.stdout.strip().split('\\n')
                if len(lines) > 1:
                    parts = lines[1].split()
                    total = parts[1] if len(parts) > 1 else 'Unknown'
                    used = parts[2] if len(parts) > 2 else 'Unknown'
                    available = parts[3] if len(parts) > 3 else 'Unknown'
                    usage_percent = parts[4] if len(parts) > 4 else 'Unknown'

                    self.results['disk'] = {
                        'total': total,
                        'used': used,
                        'available': available,
                        'usage_percent': usage_percent,
                        'status': 'OK' if usage_percent.replace('%', '').isdigit() and 
                                int(usage_percent.replace('%', '')) < 90 else 'WARNING'
                    }
                    print(f"   💾 Disk: {used}/{total} ({usage_percent}) - {available} available")

            # Check memory (if available)
            try:
                memory_info = subprocess.run(['free', '-h'], capture_output=True, text=True)
                if memory_info.returncode == 0:
                    lines = memory_info.stdout.strip().split('\\n')
                    if len(lines) > 1:
                        parts = lines[1].split()
                        total_mem = parts[1] if len(parts) > 1 else 'Unknown'
                        used_mem = parts[2] if len(parts) > 2 else 'Unknown'
                        available_mem = parts[6] if len(parts) > 6 else parts[3] if len(parts) > 3 else 'Unknown'

                        self.results['memory'] = {
                            'total': total_mem,
                            'used': used_mem,
                            'available': available_mem,
                            'status': 'OK'
                        }
                        print(f"   🧠 Memory: {used_mem}/{total_mem} - {available_mem} available")
            except:
                self.results['memory'] = {'status': 'UNAVAILABLE', 'note': 'Memory info not accessible'}
                print("   🧠 Memory: Information not available")

            # Check Python version and modules
            python_version = sys.version.split()[0]
            self.results['python'] = {
                'version': python_version,
                'executable': sys.executable,
                'status': 'OK'
            }
            print(f"   🐍 Python: {python_version} ({sys.executable})")

        except Exception as e:
            self.results['system_resources'] = {'status': 'ERROR', 'error': str(e)}
            print(f"   ❌ Error checking system resources: {e}")

    def check_network_connectivity(self):
        """Check network connectivity and API endpoints"""
        print("🌐 Checking network connectivity...")

        # Test basic internet connectivity
        test_urls = [
            'https://httpbin.org/status/200',
            'https://huggingface.co',
            'https://api.github.com'
        ]

        network_results = {}

        for url in test_urls:
            try:
                start_time = time.time()
                response = urllib.request.urlopen(url, timeout=10)
                response_time = (time.time() - start_time) * 1000  # Convert to milliseconds

                network_results[url] = {
                    'status': 'OK',
                    'response_code': response.getcode(),
                    'response_time_ms': round(response_time, 2)
                }
                print(f"   ✅ {url}: {response.getcode()} ({response_time:.1f}ms)")

            except urllib.error.URLError as e:
                network_results[url] = {
                    'status': 'ERROR',
                    'error': str(e)
                }
                print(f"   ❌ {url}: {e}")
            except Exception as e:
                network_results[url] = {
                    'status': 'ERROR', 
                    'error': str(e)
                }
                print(f"   ❌ {url}: {e}")

        self.results['network'] = network_results

    def check_huggingface_spaces(self):
        """Test HuggingFace Spaces connectivity"""
        print("🤗 Checking HuggingFace Spaces connectivity...")

        if not self.config.get('hf_spaces', {}):
            print("   ⚠️  No HuggingFace configuration found")
            self.results['hf_spaces'] = {'status': 'NO_CONFIG'}
            return

        base_url = self.config['hf_spaces'].get('base_url', 'https://huggingface.co/spaces')
        endpoints = self.config['hf_spaces'].get('endpoints', {})

        hf_results = {}

        # Test base URL
        try:
            start_time = time.time()
            response = urllib.request.urlopen(base_url, timeout=15)
            response_time = (time.time() - start_time) * 1000

            hf_results['base_url'] = {
                'url': base_url,
                'status': 'OK',
                'response_code': response.getcode(),
                'response_time_ms': round(response_time, 2)
            }
            print(f"   ✅ Base URL: {response.getcode()} ({response_time:.1f}ms)")

        except Exception as e:
            hf_results['base_url'] = {
                'url': base_url,
                'status': 'ERROR',
                'error': str(e)
            }
            print(f"   ❌ Base URL: {e}")

        # Test specific endpoints (just connectivity, not full API calls)
        for service_name, endpoint in endpoints.items():
            if service_name == 'text_generation':  # Test one endpoint as example
                test_url = f"{base_url}/{endpoint}"
                try:
                    start_time = time.time()
                    response = urllib.request.urlopen(test_url, timeout=15)
                    response_time = (time.time() - start_time) * 1000

                    hf_results[service_name] = {
                        'endpoint': endpoint,
                        'url': test_url,
                        'status': 'OK',
                        'response_code': response.getcode(),
                        'response_time_ms': round(response_time, 2)
                    }
                    print(f"   ✅ {service_name}: {response.getcode()} ({response_time:.1f}ms)")

                except Exception as e:
                    hf_results[service_name] = {
                        'endpoint': endpoint,
                        'url': test_url,
                        'status': 'ERROR',
                        'error': str(e)
                    }
                    print(f"   ❌ {service_name}: {e}")
                break  # Only test one to avoid rate limits

        self.results['hf_spaces'] = hf_results

    def check_file_permissions(self):
        """Check file and directory permissions"""
        print("📁 Checking file permissions...")

        base_dir = os.path.dirname(os.path.dirname(__file__))
        critical_paths = [
            os.path.join(base_dir, 'oasis_orchestrator.py'),
            os.path.join(base_dir, 'config'),
            os.path.join(base_dir, 'logs'),
            os.path.join(base_dir, 'modules'),
        ]

        permission_results = {}

        for path in critical_paths:
            try:
                if os.path.exists(path):
                    is_readable = os.access(path, os.R_OK)
                    is_writable = os.access(path, os.W_OK) if os.path.isdir(path) else True
                    is_executable = os.access(path, os.X_OK) if os.path.isfile(path) else True

                    permission_results[path] = {
                        'exists': True,
                        'readable': is_readable,
                        'writable': is_writable,
                        'executable': is_executable,
                        'status': 'OK' if is_readable and (is_writable or not os.path.isdir(path)) else 'WARNING'
                    }

                    status_icon = "✅" if permission_results[path]['status'] == 'OK' else "⚠️"
                    permissions = []
                    if is_readable: permissions.append('R')
                    if is_writable: permissions.append('W')
                    if is_executable: permissions.append('X')

                    print(f"   {status_icon} {os.path.basename(path)}: {''.join(permissions)}")
                else:
                    permission_results[path] = {
                        'exists': False,
                        'status': 'MISSING'
                    }
                    print(f"   ❌ {os.path.basename(path)}: Missing")

            except Exception as e:
                permission_results[path] = {
                    'status': 'ERROR',
                    'error': str(e)
                }
                print(f"   ❌ {os.path.basename(path)}: {e}")

        self.results['file_permissions'] = permission_results

    def check_configuration(self):
        """Validate configuration settings"""
        print("⚙️  Checking configuration...")

        config_results = {}

        if not self.config:
            config_results['status'] = 'ERROR'
            config_results['error'] = 'Configuration not loaded'
            print("   ❌ Configuration file not loaded")
            self.results['configuration'] = config_results
            return

        # Check required sections
        required_sections = ['oasis', 'hf_spaces', 'task_manager', 'logging']
        missing_sections = []

        for section in required_sections:
            if section not in self.config:
                missing_sections.append(section)
            else:
                print(f"   ✅ {section}: Present")

        if missing_sections:
            config_results['missing_sections'] = missing_sections
            config_results['status'] = 'WARNING'
            print(f"   ⚠️  Missing sections: {', '.join(missing_sections)}")
        else:
            config_results['status'] = 'OK'

        # Check version
        oasis_config = self.config.get('oasis', {})
        version = oasis_config.get('version', 'Unknown')
        print(f"   📋 Version: {version}")

        config_results['version'] = version
        config_results['sections_present'] = list(self.config.keys())

        self.results['configuration'] = config_results

    def generate_report(self):
        """Generate comprehensive health report"""
        execution_time = time.time() - self.start_time

        print("\\n" + "="*60)
        print("📊 OASIS v3 Health Check Report")
        print("="*60)

        # Overall status
        overall_status = "OK"
        warning_count = 0
        error_count = 0

        for category, result in self.results.items():
            if isinstance(result, dict):
                status = result.get('status', 'UNKNOWN')
                if status in ['ERROR', 'MISSING']:
                    error_count += 1
                    overall_status = "ERROR"
                elif status == 'WARNING':
                    warning_count += 1
                    if overall_status != "ERROR":
                        overall_status = "WARNING"

        status_icon = "✅" if overall_status == "OK" else "⚠️" if overall_status == "WARNING" else "❌"
        print(f"\\nOverall Status: {status_icon} {overall_status}")

        if error_count > 0:
            print(f"Errors: {error_count}")
        if warning_count > 0:
            print(f"Warnings: {warning_count}")

        print(f"Execution Time: {execution_time:.2f} seconds")
        print(f"Timestamp: {datetime.now().isoformat()}")

        # Detailed results
        print("\\n" + "="*40)
        print("📋 Detailed Results")
        print("="*40)

        for category, result in self.results.items():
            print(f"\\n{category.upper().replace('_', ' ')}:")
            if isinstance(result, dict):
                for key, value in result.items():
                    if isinstance(value, dict):
                        print(f"  {key}:")
                        for subkey, subvalue in value.items():
                            print(f"    {subkey}: {subvalue}")
                    else:
                        print(f"  {key}: {value}")
            else:
                print(f"  {result}")

        # Save report to file
        report_data = {
            'timestamp': datetime.now().isoformat(),
            'overall_status': overall_status,
            'execution_time': execution_time,
            'error_count': error_count,
            'warning_count': warning_count,
            'results': self.results
        }

        try:
            logs_dir = os.path.join(os.path.dirname(os.path.dirname(__file__)), 'logs')
            os.makedirs(logs_dir, exist_ok=True)

            report_file = os.path.join(logs_dir, f'health_check_{datetime.now().strftime("%Y%m%d_%H%M%S")}.json')

            with open(report_file, 'w') as f:
                json.dump(report_data, f, indent=2)

            print(f"\\n📁 Report saved to: {report_file}")
        except Exception as e:
            print(f"\\n⚠️  Could not save report: {e}")

        return overall_status, self.results

    def run_all_checks(self):
        """Run all health checks"""
        print("🚀 Starting OASIS v3 Health Check...")
        print("="*50)

        checks = [
            self.check_system_resources,
            self.check_configuration,
            self.check_file_permissions,
            self.check_network_connectivity,
            self.check_huggingface_spaces,
        ]

        for check in checks:
            try:
                check()
            except Exception as e:
                print(f"❌ Error in {check.__name__}: {e}")
                self.results[check.__name__] = {'status': 'ERROR', 'error': str(e)}
            print()  # Add spacing between checks

        return self.generate_report()

def main():
    """Main function for CLI usage"""
    import argparse

    parser = argparse.ArgumentParser(description='OASIS v3 Health Check System')
    parser.add_argument('--config', help='Path to configuration file')
    parser.add_argument('--quick', action='store_true', help='Run quick checks only')
