revenue_tracker_script = '''#!/usr/bin/env python3
"""
OASIS v3 Revenue Tracker
Ultra-lightweight revenue monitoring and earnings analysis
Uses only Python standard library
"""

import json
import time
import os
from datetime import datetime, timedelta
from decimal import Decimal, ROUND_HALF_UP
import threading
import logging

class RevenueTracker:
    def __init__(self, config_path=None, data_file=None):
        self.config_path = config_path or os.path.join('config', 'config.json')
        self.data_file = data_file or os.path.join('data', 'revenue_data.json')
        self.config = self.load_config()
        self.lock = threading.Lock()

        # Revenue data structure
        self.revenue_data = {
            'daily_revenue': {},
            'monthly_revenue': {},
            'service_usage': {},
            'client_revenue': {},
            'transactions': [],
            'targets': {},
            'metrics': {}
        }

        self.load_revenue_data()
        self.setup_logging()

    def setup_logging(self):
        """Setup revenue tracking logging"""
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger('RevenueTracker')

    def load_config(self):
        """Load configuration"""
        try:
            with open(self.config_path, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Warning: Could not load config: {e}")
            return {}

    def load_revenue_data(self):
        """Load existing revenue data"""
        try:
            if os.path.exists(self.data_file):
                with open(self.data_file, 'r') as f:
                    loaded_data = json.load(f)
                    self.revenue_data.update(loaded_data)
                self.logger.info("Revenue data loaded successfully")
            else:
                self.logger.info("No existing revenue data found, starting fresh")
        except Exception as e:
            self.logger.error(f"Error loading revenue data: {e}")

    def save_revenue_data(self):
        """Save revenue data to file"""
        try:
            os.makedirs(os.path.dirname(self.data_file), exist_ok=True)

            with self.lock:
                with open(self.data_file, 'w') as f:
                    json.dump(self.revenue_data, f, indent=2)

            self.logger.info("Revenue data saved successfully")
        except Exception as e:
            self.logger.error(f"Error saving revenue data: {e}")

    def record_transaction(self, service_type, amount, client_id=None, metadata=None):
        """Record a revenue transaction"""
        transaction = {
            'timestamp': datetime.now().isoformat(),
            'service_type': service_type,
            'amount': float(Decimal(str(amount)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)),
            'client_id': client_id,
            'metadata': metadata or {}
        }

        with self.lock:
            # Add to transactions log
            self.revenue_data['transactions'].append(transaction)

            # Update daily revenue
            today = datetime.now().strftime('%Y-%m-%d')
            if today not in self.revenue_data['daily_revenue']:
                self.revenue_data['daily_revenue'][today] = 0.0
            self.revenue_data['daily_revenue'][today] += transaction['amount']

            # Update monthly revenue
            month = datetime.now().strftime('%Y-%m')
            if month not in self.revenue_data['monthly_revenue']:
                self.revenue_data['monthly_revenue'][month] = 0.0
            self.revenue_data['monthly_revenue'][month] += transaction['amount']

            # Update service usage
            if service_type not in self.revenue_data['service_usage']:
                self.revenue_data['service_usage'][service_type] = {
                    'count': 0,
                    'revenue': 0.0
                }
            self.revenue_data['service_usage'][service_type]['count'] += 1
            self.revenue_data['service_usage'][service_type]['revenue'] += transaction['amount']

            # Update client revenue
            if client_id:
                if client_id not in self.revenue_data['client_revenue']:
                    self.revenue_data['client_revenue'][client_id] = {
                        'total_revenue': 0.0,
                        'transaction_count': 0,
                        'services_used': set()
                    }

                self.revenue_data['client_revenue'][client_id]['total_revenue'] += transaction['amount']
                self.revenue_data['client_revenue'][client_id]['transaction_count'] += 1
                self.revenue_data['client_revenue'][client_id]['services_used'].add(service_type)

                # Convert set to list for JSON serialization
                self.revenue_data['client_revenue'][client_id]['services_used'] = list(
                    self.revenue_data['client_revenue'][client_id]['services_used']
                )

        self.save_revenue_data()
        self.logger.info(f"Transaction recorded: {service_type} - ${transaction['amount']:.2f}")

        return transaction

    def get_daily_revenue(self, date=None):
        """Get revenue for a specific date"""
        if date is None:
            date = datetime.now().strftime('%Y-%m-%d')
        elif isinstance(date, datetime):
            date = date.strftime('%Y-%m-%d')

        return self.revenue_data['daily_revenue'].get(date, 0.0)

    def get_monthly_revenue(self, month=None):
        """Get revenue for a specific month"""
        if month is None:
            month = datetime.now().strftime('%Y-%m')
        elif isinstance(month, datetime):
            month = month.strftime('%Y-%m')

        return self.revenue_data['monthly_revenue'].get(month, 0.0)

    def get_revenue_trend(self, days=30):
        """Get revenue trend for the last N days"""
        end_date = datetime.now()
        start_date = end_date - timedelta(days=days)

        trend_data = []
        current_date = start_date

        while current_date <= end_date:
            date_str = current_date.strftime('%Y-%m-%d')
            revenue = self.get_daily_revenue(date_str)

            trend_data.append({
                'date': date_str,
                'revenue': revenue,
                'day_of_week': current_date.strftime('%A'),
                'cumulative': sum(item['revenue'] for item in trend_data) + revenue
            })

            current_date += timedelta(days=1)

        return trend_data

    def get_service_performance(self):
        """Get performance metrics for each service"""
        performance = {}

        for service, data in self.revenue_data['service_usage'].items():
            if data['count'] > 0:
                performance[service] = {
                    'total_requests': data['count'],
                    'total_revenue': data['revenue'],
                    'average_revenue_per_request': data['revenue'] / data['count'],
                    'percentage_of_total_revenue': 0.0
                }

        # Calculate percentages
        total_revenue = sum(data['total_revenue'] for data in performance.values())
        if total_revenue > 0:
            for service in performance:
                performance[service]['percentage_of_total_revenue'] = (
                    performance[service]['total_revenue'] / total_revenue * 100
                )

        return performance

    def get_client_analysis(self):
        """Get client revenue analysis"""
        client_analysis = {}

        for client_id, data in self.revenue_data['client_revenue'].items():
            client_analysis[client_id] = {
                'total_revenue': data['total_revenue'],
                'transaction_count': data['transaction_count'],
                'average_transaction_value': (
                    data['total_revenue'] / data['transaction_count'] 
                    if data['transaction_count'] > 0 else 0.0
                ),
                'services_used': data.get('services_used', []),
                'service_diversity': len(data.get('services_used', []))
            }

        # Sort by revenue
        sorted_clients = sorted(
            client_analysis.items(), 
            key=lambda x: x[1]['total_revenue'], 
            reverse=True
        )

        return dict(sorted_clients)

    def check_targets(self):
        """Check progress against revenue targets"""
        config_targets = self.config.get('business', {}).get('revenue_targets', {})

        # Current month progress
        current_month_revenue = self.get_monthly_revenue()
        monthly_target = config_targets.get('monthly_min', 10000)
        monthly_max = config_targets.get('monthly_max', 50000)

        # Today's progress
        today_revenue = self.get_daily_revenue()
        daily_target = config_targets.get('daily_target', 333)

        # Calculate progress percentages
        monthly_progress = (current_month_revenue / monthly_target * 100) if monthly_target > 0 else 0
        daily_progress = (today_revenue / daily_target * 100) if daily_target > 0 else 0

        # Days remaining in month
        now = datetime.now()
        last_day = (now.replace(day=28) + timedelta(days=4)).replace(day=1) - timedelta(days=1)
        days_remaining = (last_day - now).days + 1

        target_status = {
            'monthly': {
                'current': current_month_revenue,
                'target_min': monthly_target,
                'target_max': monthly_max,
                'progress_percent': monthly_progress,
                'remaining_needed': max(0, monthly_target - current_month_revenue),
                'days_remaining': days_remaining,
                'status': 'on_track' if monthly_progress >= 75 else 'behind' if monthly_progress < 50 else 'attention_needed'
            },
            'daily': {
                'current': today_revenue,
                'target': daily_target,
                'progress_percent': daily_progress,
                'status': 'exceeded' if daily_progress >= 100 else 'on_track' if daily_progress >= 75 else 'behind'
            }
        }

        return target_status

    def generate_revenue_report(self, period='monthly'):
        """Generate comprehensive revenue report"""
        report_data = {
            'report_timestamp': datetime.now().isoformat(),
            'period': period,
            'summary': {},
            'targets': self.check_targets(),
            'service_performance': self.get_service_performance(),
            'client_analysis': self.get_client_analysis(),
            'trends': {}
        }

        if period == 'daily':
            report_data['summary'] = {
                'today_revenue': self.get_daily_revenue(),
                'yesterday_revenue': self.get_daily_revenue(
                    (datetime.now() - timedelta(days=1)).strftime('%Y-%m-%d')
                ),
                'week_to_date': sum(
                    self.get_daily_revenue((datetime.now() - timedelta(days=i)).strftime('%Y-%m-%d'))
                    for i in range(7)
                )
            }
            report_data['trends']['daily_trend'] = self.get_revenue_trend(7)

        elif period == 'monthly':
            report_data['summary'] = {
                'current_month': self.get_monthly_revenue(),
                'last_month': self.get_monthly_revenue(
                    (datetime.now().replace(day=1) - timedelta(days=1)).strftime('%Y-%m')
                ),
                'year_to_date': sum(
                    revenue for month, revenue in self.revenue_data['monthly_revenue'].items()
                    if month.startswith(str(datetime.now().year))
                )
            }
            report_data['trends']['monthly_trend'] = self.get_revenue_trend(30)

        return report_data

    def export_revenue_data(self, filename=None, format='json'):
        """Export revenue data to file"""
        if filename is None:
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            filename = f"revenue_export_{timestamp}.{format}"

        try:
            if format == 'json':
                with open(filename, 'w') as f:
                    json.dump(self.revenue_data, f, indent=2)

            elif format == 'csv':
                # Export transactions as CSV
                import csv
                with open(filename, 'w', newline='') as f:
                    writer = csv.writer(f)
                    writer.writerow(['Timestamp', 'Service', 'Amount', 'Client', 'Metadata'])

                    for transaction in self.revenue_data['transactions']:
                        writer.writerow([
                            transaction['timestamp'],
                            transaction['service_type'],
                            transaction['amount'],
                            transaction.get('client_id', ''),
                            json.dumps(transaction.get('metadata', {}))
                        ])

            self.logger.info(f"Revenue data exported to {filename}")
            return filename

        except Exception as e:
            self.logger.error(f"Export failed: {e}")
            return None

    def get_real_time_metrics(self):
        """Get real-time revenue metrics"""
        now = datetime.now()

        # Calculate various time-based metrics
        today_revenue = self.get_daily_revenue()
        hour_start = now.replace(minute=0, second=0, microsecond=0)

        # Recent transactions (last hour)
        recent_transactions = [
            t for t in self.revenue_data['transactions']
            if datetime.fromisoformat(t['timestamp']) >= hour_start
        ]

        hourly_revenue = sum(t['amount'] for t in recent_transactions)

        metrics = {
            'timestamp': now.isoformat(),
            'today_revenue': today_revenue,
            'hourly_revenue': hourly_revenue,
            'recent_transaction_count': len(recent_transactions),
            'average_transaction_value': (
                sum(t['amount'] for t in recent_transactions) / len(recent_transactions)
                if recent_transactions else 0.0
            ),
            'revenue_velocity': {
                'per_hour': hourly_revenue,
                'per_day_projected': hourly_revenue * 24 if hourly_revenue > 0 else today_revenue,
                'per_month_projected': (today_revenue * 30) if today_revenue > 0 else 0
            },
            'top_service_today': None,
            'total_transactions_today': len([
                t for t in self.revenue_data['transactions']
                if t['timestamp'].startswith(now.strftime('%Y-%m-%d'))
            ])
        }

        # Find top performing service today
        today_services = {}
        for transaction in self.revenue_data['transactions']:
            if transaction['timestamp'].startswith(now.strftime('%Y-%m-%d')):
                service = transaction['service_type']
                if service not in today_services:
                    today_services[service] = 0
                today_services[service] += transaction['amount']

        if today_services:
            top_service = max(today_services.items(), key=lambda x: x[1])
            metrics['top_service_today'] = {
                'service': top_service[0],
                'revenue': top_service[1]
            }

        return metrics

def main():
    """CLI interface for revenue tracker"""
    import argparse

    parser = argparse.ArgumentParser(description='OASIS v3 Revenue Tracker')
    parser.add_argument('--config', help='Path to configuration file')
    parser.add_argument('--data-file', help='Path to revenue data file')
