        print(f"Recent Transactions: {metrics['recent_transaction_count']}")
        print(f"Avg Transaction: ${metrics['average_transaction_value']:.2f}")
        print(f"Projected Daily: ${metrics['revenue_velocity']['per_day_projected']:.2f}")

        if metrics['top_service_today']:
            print(f"Top Service Today: {metrics['top_service_today']['service']} (${metrics['top_service_today']['revenue']:.2f})")

    elif args.targets:
        targets = tracker.check_targets()
        print("🎯 Revenue Targets Progress")
        print("=" * 40)

