client_manager_script = '''#!/usr/bin/env python3
"""
OASIS v3 Client Manager
Ultra-lightweight customer management system
Uses only Python standard library
"""

import json
import os
import time
from datetime import datetime, timedelta
import logging
import hashlib

class ClientManager:
    def __init__(self, config_path=None, data_file=None):
        self.config_path = config_path or os.path.join('config', 'config.json')
        self.data_file = data_file or os.path.join('data', 'clients.json')
        self.config = self.load_config()

        # Client data structure
        self.clients = {}
        self.load_client_data()
        self.setup_logging()

    def setup_logging(self):
        """Setup client management logging"""
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger('ClientManager')

    def load_config(self):
        """Load configuration"""
        try:
            with open(self.config_path, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Warning: Could not load config: {e}")
            return {}

    def load_client_data(self):
        """Load existing client data"""
        try:
            if os.path.exists(self.data_file):
                with open(self.data_file, 'r') as f:
                    self.clients = json.load(f)
                self.logger.info("Client data loaded successfully")
            else:
                self.logger.info("No existing client data found, starting fresh")
        except Exception as e:
            self.logger.error(f"Error loading client data: {e}")

    def save_client_data(self):
        """Save client data to file"""
        try:
            os.makedirs(os.path.dirname(self.data_file), exist_ok=True)
            with open(self.data_file, 'w') as f:
                json.dump(self.clients, f, indent=2)
            self.logger.info("Client data saved successfully")
        except Exception as e:
            self.logger.error(f"Error saving client data: {e}")

    def generate_client_id(self, email):
        """Generate unique client ID from email"""
        return hashlib.md5(email.encode()).hexdigest()[:12]

    def create_client(self, email, name, tier='free'):
        """Create a new client"""
        client_id = self.generate_client_id(email)

        if client_id in self.clients:
            self.logger.warning(f"Client already exists: {email}")
            return None

        client_data = {
            'client_id': client_id,
            'email': email,
            'name': name,
            'tier': tier,
            'created_at': datetime.now().isoformat(),
            'last_active': datetime.now().isoformat(),
            'api_calls': 0,
            'total_revenue': 0.0,
            'status': 'active',
            'settings': {
                'rate_limit': self.get_tier_limits(tier)['rate_limit'],
                'daily_requests': self.get_tier_limits(tier)['requests_per_day']
            }
        }

        self.clients[client_id] = client_data
        self.save_client_data()

        self.logger.info(f"Created new client: {name} ({email}) - {tier}")
        return client_id

    def get_tier_limits(self, tier):
        """Get limits for client tier"""
        tier_config = self.config.get('business', {}).get('client_tiers', {})
        return tier_config.get(tier, tier_config.get('free', {
            'requests_per_day': 100,
            'rate_limit': 10
        }))

    def update_client_activity(self, client_id, service_used=None, amount_charged=0.0):
        """Update client activity and usage"""
        if client_id not in self.clients:
            self.logger.error(f"Client not found: {client_id}")
            return False

        client = self.clients[client_id]
        client['last_active'] = datetime.now().isoformat()
        client['api_calls'] += 1
        client['total_revenue'] += amount_charged

        if service_used:
            if 'services_used' not in client:
                client['services_used'] = {}

            if service_used not in client['services_used']:
                client['services_used'][service_used] = {
                    'count': 0,
                    'revenue': 0.0,
                    'first_used': datetime.now().isoformat()
                }

            client['services_used'][service_used]['count'] += 1
            client['services_used'][service_used]['revenue'] += amount_charged
            client['services_used'][service_used]['last_used'] = datetime.now().isoformat()

        self.save_client_data()
        return True

    def get_client(self, client_id):
        """Get client information"""
        return self.clients.get(client_id)

    def check_client_limits(self, client_id):
        """Check if client has exceeded limits"""
        client = self.get_client(client_id)
        if not client:
            return {'allowed': False, 'reason': 'Client not found'}

        # Check daily request limit
        today = datetime.now().strftime('%Y-%m-%d')
        daily_calls = 0

        # Count today's API calls (simplified - would need more detailed tracking)
        if client['last_active'].startswith(today):
            daily_calls = client['api_calls']  # Simplified calculation

        tier_limits = self.get_tier_limits(client['tier'])
        daily_limit = tier_limits.get('requests_per_day', 100)

        if daily_calls >= daily_limit:
            return {
                'allowed': False,
                'reason': 'Daily request limit exceeded',
                'limit': daily_limit,
                'used': daily_calls
            }

        return {
            'allowed': True,
            'limit': daily_limit,
            'used': daily_calls,
            'remaining': daily_limit - daily_calls
        }

    def get_client_stats(self):
        """Get overall client statistics"""
        total_clients = len(self.clients)
        active_clients = len([c for c in self.clients.values() if c['status'] == 'active'])

        tier_counts = {}
        total_revenue = 0.0
        total_api_calls = 0

        for client in self.clients.values():
            tier = client['tier']
            tier_counts[tier] = tier_counts.get(tier, 0) + 1
            total_revenue += client.get('total_revenue', 0.0)
            total_api_calls += client.get('api_calls', 0)

        return {
            'total_clients': total_clients,
            'active_clients': active_clients,
            'tier_distribution': tier_counts,
            'total_revenue': total_revenue,
            'total_api_calls': total_api_calls,
            'average_revenue_per_client': total_revenue / total_clients if total_clients > 0 else 0
        }

def main():
    """CLI interface for client manager"""
    manager = ClientManager()

    print("👥 OASIS v3 Client Manager")
    print("=" * 40)

    stats = manager.get_client_stats()
    print(f"Total Clients: {stats['total_clients']}")
    print(f"Active Clients: {stats['active_clients']}")
    print(f"Total Revenue: ${stats['total_revenue']:.2f}")
    print(f"Total API Calls: {stats['total_api_calls']}")

    if stats['tier_distribution']:
        print("\\nTier Distribution:")
        for tier, count in stats['tier_distribution'].items():
            print(f"  {tier}: {count}")

if __name__ == "__main__":
    main()
