# Create analytics.py for performance metrics
analytics_script = '''#!/usr/bin/env python3
"""
OASIS v3 Analytics System
Ultra-lightweight performance monitoring and analytics
Uses only Python standard library
"""

import json
import os
import time
from datetime import datetime, timedelta
import logging
import statistics

class AnalyticsEngine:
    def __init__(self, config_path=None, data_file=None):
        self.config_path = config_path or os.path.join('config', 'config.json')
        self.data_file = data_file or os.path.join('data', 'analytics.json')
        self.config = self.load_config()

        # Analytics data structure
        self.analytics_data = {
            'performance_metrics': [],
            'service_usage': {},
            'response_times': {},
            'error_rates': {},
            'daily_stats': {},
            'system_metrics': []
        }

        self.load_analytics_data()
        self.setup_logging()

    def setup_logging(self):
        """Setup analytics logging"""
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger('AnalyticsEngine')

    def load_config(self):
        """Load configuration"""
        try:
            with open(self.config_path, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Warning: Could not load config: {e}")
            return {}

    def load_analytics_data(self):
        """Load existing analytics data"""
        try:
            if os.path.exists(self.data_file):
                with open(self.data_file, 'r') as f:
                    self.analytics_data = json.load(f)
                self.logger.info("Analytics data loaded successfully")
            else:
                self.logger.info("No existing analytics data found, starting fresh")
        except Exception as e:
            self.logger.error(f"Error loading analytics data: {e}")

    def save_analytics_data(self):
        """Save analytics data to file"""
        try:
            os.makedirs(os.path.dirname(self.data_file), exist_ok=True)
            with open(self.data_file, 'w') as f:
                json.dump(self.analytics_data, f, indent=2)
        except Exception as e:
            self.logger.error(f"Error saving analytics data: {e}")

    def record_request(self, service_type, response_time, success=True, client_id=None):
        """Record an API request for analytics"""
        timestamp = datetime.now().isoformat()

        # Record performance metric
        metric = {
            'timestamp': timestamp,
            'service_type': service_type,
            'response_time': response_time,
            'success': success,
            'client_id': client_id
        }

        self.analytics_data['performance_metrics'].append(metric)

        # Update service usage
        if service_type not in self.analytics_data['service_usage']:
            self.analytics_data['service_usage'][service_type] = {
                'total_requests': 0,
                'successful_requests': 0,
                'failed_requests': 0,
                'total_response_time': 0.0
            }

        usage = self.analytics_data['service_usage'][service_type]
        usage['total_requests'] += 1
        usage['total_response_time'] += response_time

        if success:
            usage['successful_requests'] += 1
        else:
            usage['failed_requests'] += 1

        # Update response times
        if service_type not in self.analytics_data['response_times']:
            self.analytics_data['response_times'][service_type] = []

        self.analytics_data['response_times'][service_type].append(response_time)

        # Keep only last 1000 response times per service to manage memory
        if len(self.analytics_data['response_times'][service_type]) > 1000:
            self.analytics_data['response_times'][service_type] = \
                self.analytics_data['response_times'][service_type][-1000:]

        # Update daily stats
        today = datetime.now().strftime('%Y-%m-%d')
        if today not in self.analytics_data['daily_stats']:
            self.analytics_data['daily_stats'][today] = {
                'total_requests': 0,
                'successful_requests': 0,
                'failed_requests': 0,
                'average_response_time': 0.0,
                'services_used': set()
            }

        daily = self.analytics_data['daily_stats'][today]
        daily['total_requests'] += 1
        daily['services_used'].add(service_type)

        if success:
            daily['successful_requests'] += 1
        else:
            daily['failed_requests'] += 1

        # Convert set to list for JSON serialization
        daily['services_used'] = list(daily['services_used'])

        # Keep only last 30 days of performance metrics to manage memory
        thirty_days_ago = (datetime.now() - timedelta(days=30)).isoformat()
        self.analytics_data['performance_metrics'] = [
            m for m in self.analytics_data['performance_metrics']
            if m['timestamp'] > thirty_days_ago
        ]

        self.save_analytics_data()

    def get_service_performance(self, service_type=None):
        """Get performance statistics for services"""
        if service_type:
            if service_type not in self.analytics_data['service_usage']:
                return None

            usage = self.analytics_data['service_usage'][service_type]
            response_times = self.analytics_data['response_times'].get(service_type, [])

            return {
                'service': service_type,
                'total_requests': usage['total_requests'],
                'success_rate': (usage['successful_requests'] / usage['total_requests'] * 100) 
                               if usage['total_requests'] > 0 else 0,
                'average_response_time': (usage['total_response_time'] / usage['total_requests']) 
                                       if usage['total_requests'] > 0 else 0,
                'median_response_time': statistics.median(response_times) if response_times else 0,
                'max_response_time': max(response_times) if response_times else 0,
                'min_response_time': min(response_times) if response_times else 0
            }

        # Return all services
        performance = {}
        for service in self.analytics_data['service_usage']:
            performance[service] = self.get_service_performance(service)

        return performance

    def get_daily_analytics(self, date=None):
        """Get analytics for a specific date"""
        if date is None:
            date = datetime.now().strftime('%Y-%m-%d')
        elif isinstance(date, datetime):
            date = date.strftime('%Y-%m-%d')

        return self.analytics_data['daily_stats'].get(date, {})

    def get_trend_analysis(self, days=7):
        """Get trend analysis for the last N days"""
        end_date = datetime.now()
        start_date = end_date - timedelta(days=days)

        trend_data = []
        current_date = start_date

        while current_date <= end_date:
            date_str = current_date.strftime('%Y-%m-%d')
            daily_stats = self.get_daily_analytics(date_str)

            trend_data.append({
                'date': date_str,
                'total_requests': daily_stats.get('total_requests', 0),
                'success_rate': (
                    (daily_stats.get('successful_requests', 0) / 
                     daily_stats.get('total_requests', 1)) * 100
                ) if daily_stats.get('total_requests', 0) > 0 else 0,
                'services_used': len(daily_stats.get('services_used', [])),
                'day_of_week': current_date.strftime('%A')
            })

            current_date += timedelta(days=1)

        return trend_data

    def get_system_health(self):
        """Get overall system health metrics"""
        total_requests = sum(
            service['total_requests'] 
            for service in self.analytics_data['service_usage'].values()
        )

        total_successful = sum(
            service['successful_requests'] 
            for service in self.analytics_data['service_usage'].values()
        )

        overall_success_rate = (total_successful / total_requests * 100) if total_requests > 0 else 0

        # Calculate average response time across all services
        all_response_times = []
        for times in self.analytics_data['response_times'].values():
            all_response_times.extend(times)

        avg_response_time = statistics.mean(all_response_times) if all_response_times else 0

        # Today's performance
        today_stats = self.get_daily_analytics()

        return {
            'overall_success_rate': overall_success_rate,
            'total_requests': total_requests,
            'average_response_time': avg_response_time,
            'services_available': len(self.analytics_data['service_usage']),
            'today': {
                'requests': today_stats.get('total_requests', 0),
                'success_rate': (
                    (today_stats.get('successful_requests', 0) / 
                     today_stats.get('total_requests', 1)) * 100
                ) if today_stats.get('total_requests', 0) > 0 else 0,
                'services_used': len(today_stats.get('services_used', []))
            },
            'peak_performance': {
                'fastest_service': self.get_fastest_service(),
                'most_used_service': self.get_most_used_service()
            }
        }

    def get_fastest_service(self):
        """Get the service with best average response time"""
        fastest = None
        best_time = float('inf')

        for service, usage in self.analytics_data['service_usage'].items():
            if usage['total_requests'] > 0:
                avg_time = usage['total_response_time'] / usage['total_requests']
                if avg_time < best_time:
                    best_time = avg_time
                    fastest = service

        return {'service': fastest, 'avg_response_time': best_time} if fastest else None

    def get_most_used_service(self):
        """Get the most frequently used service"""
        most_used = None
        max_requests = 0

        for service, usage in self.analytics_data['service_usage'].items():
            if usage['total_requests'] > max_requests:
                max_requests = usage['total_requests']
                most_used = service

        return {'service': most_used, 'total_requests': max_requests} if most_used else None

    def generate_analytics_report(self):
        """Generate comprehensive analytics report"""
        return {
            'report_timestamp': datetime.now().isoformat(),
            'system_health': self.get_system_health(),
            'service_performance': self.get_service_performance(),
            'trend_analysis': self.get_trend_analysis(7),
            'summary': {
                'data_points': len(self.analytics_data['performance_metrics']),
                'services_tracked': len(self.analytics_data['service_usage']),
                'days_of_data': len(self.analytics_data['daily_stats'])
            }
        }

def main():
    """CLI interface for analytics engine"""
    analytics = AnalyticsEngine()

    print("📊 OASIS v3 Analytics Dashboard")
    print("=" * 50)

    health = analytics.get_system_health()

    print(f"Overall Success Rate: {health['overall_success_rate']:.1f}%")
    print(f"Total Requests: {health['total_requests']}")
    print(f"Average Response Time: {health['average_response_time']:.2f}s")
    print(f"Services Available: {health['services_available']}")

    print("\\nToday's Performance:")
    print(f"  Requests: {health['today']['requests']}")
    print(f"  Success Rate: {health['today']['success_rate']:.1f}%")
    print(f"  Services Used: {health['today']['services_used']}")

    if health['peak_performance']['fastest_service']:
        fastest = health['peak_performance']['fastest_service']
        print(f"\\nFastest Service: {fastest['service']} ({fastest['avg_response_time']:.2f}s)")

    if health['peak_performance']['most_used_service']:
        popular = health['peak_performance']['most_used_service']
        print(f"Most Used Service: {popular['service']} ({popular['total_requests']} requests)")

if __name__ == "__main__":
    main()
'''

